+// API keys, roles and the audit log. A key belongs to one role:
+//   viewer  — may only read (GET);
+//   cook    — may also cook, record waste, log temperatures and enter counts;
+//   manager — may do everything.
+// Some reads are for managers only (the audit log).
+import { timingSafeEqual } from "node:crypto";
+
+/** Roles, from least to most allowed. */
+export const ROLES = Object.freeze(["viewer", "cook", "manager"]);
+
+// Routes ("METHOD /pattern") a cook may call beyond reading.
+const COOK_ROUTES = new Set([
+  "POST /recipes/:id/cook",
+  "POST /batches/:id/waste",
+  "POST /temperatures",
+  "POST /stocktakes/:id/counts",
+]);
+
+// Routes only managers may call, even though they only read.
+const MANAGER_ONLY = new Set(["GET /audit"]);
+
+function sameKey(a, b) {
+  const x = Buffer.from(String(a));
+  const y = Buffer.from(String(b));
+  return x.length === y.length && timingSafeEqual(x, y);
+}
+
+/** The API key record for `key`, or null when it is missing or unknown. */
+export function findKey(store, key) {
+  if (typeof key !== "string" || key === "") return null;
+  return (store.data.apiKeys ?? []).find((k) => sameKey(k.key, key)) ?? null;
+}
+
+/** Whether `role` may call the route `method pattern`. */
+export function allowed(role, method, pattern) {
+  const route = `${method} ${pattern}`;
+  if (role === "manager") return true;
+  if (MANAGER_ONLY.has(route)) return false;
+  if (method === "GET") return role === "viewer" || role === "cook";
+  return role === "cook" && COOK_ROUTES.has(route);
+}
+
+/** Appends an audit entry { id, at, keyName, method, path, status }; returns it. */
+export function recordAudit(store, { keyName, method, path, status }, { at }) {
+  store.data.audit ??= [];
+  const entry = { id: store.nextId("audit"), at, keyName, method, path, status };
+  store.data.audit.push(entry);
+  return entry;
+}
+
+/** Audit entries, newest first. */
+export function listAudit(store) {
+  return [...(store.data.audit ?? [])].sort((a, b) => (a.at < b.at ? 1 : a.at > b.at ? -1 : b.id - a.id));
+}
