+++ b/tests/access.test.js
@@ -0,0 +1,59 @@
+import test from "node:test";
+import assert from "node:assert/strict";
+import { app, KEYS } from "./helpers.js";
+
+test("requests without a key or with an unknown key are 401", async () => {
+  const { handle, store } = app();
+  const none = await handle({ path: "/items", headers: {} });
+  assert.equal(none.status, 401);
+  assert.equal(none.body.error.code, "unauthorized");
+  const unknown = await handle({ path: "/items", headers: { authorization: "Bearer nope" } });
+  assert.equal(unknown.status, 401);
+  const notBearer = await handle({ path: "/items", headers: { authorization: KEYS.manager } });
+  assert.equal(notBearer.status, 401);
+  const before = JSON.stringify(store.data.batches);
+  const post = await handle({ method: "POST", path: "/recipes/1/cook", headers: {}, body: { portions: 1 } });
+  assert.equal(post.status, 401);
+  assert.equal(JSON.stringify(store.data.batches), before);
+});
+
+test("viewers may only read", async () => {
+  const { handle } = app(undefined, { key: KEYS.viewer });
+  assert.equal((await handle({ path: "/items" })).status, 200);
+  const cook = await handle({ method: "POST", path: "/recipes/1/cook", body: { portions: 1 } });
+  assert.equal(cook.status, 403);
+  assert.equal(cook.body.error.code, "forbidden");
+  assert.equal((await handle({ path: "/audit" })).status, 403);
+});
+
+test("cooks may cook, waste, log temperatures and count, nothing else", async () => {
+  const { handle, store } = app(undefined, { key: KEYS.cook });
+  assert.equal((await handle({ method: "POST", path: "/recipes/1/cook", body: { portions: 1 } })).status, 200);
+  assert.equal((await handle({ method: "POST", path: "/batches/1/waste", body: { qty: 0.5, reason: "spoiled" } })).status, 201);
+  assert.equal((await handle({ method: "POST", path: "/temperatures", body: { location: "fridge", celsius: 3 } })).status, 201);
+  assert.equal((await handle({ method: "POST", path: "/stocktakes", body: { location: "dry" } })).status, 403);
+  const manager = app(store).handle;
+  const take = (await manager({ method: "POST", path: "/stocktakes", body: { location: "dry" } })).body;
+  assert.equal((await handle({ method: "POST", path: `/stocktakes/${take.id}/counts`, body: { batchId: 6, counted: 12 } })).status, 200);
+  assert.equal((await handle({ method: "POST", path: `/stocktakes/${take.id}/finish` })).status, 403);
+  assert.equal((await handle({ method: "POST", path: "/orders", body: { supplierId: 1, lines: [] } })).status, 403);
+  assert.equal((await handle({ path: "/audit" })).status, 403);
+});
+
+test("changes are audited and managers read the log newest first", async () => {
+  const { handle, store } = app(undefined, { key: KEYS.cook });
+  await handle({ method: "POST", path: "/recipes/1/cook", body: { portions: 1 } });
+  await handle({ method: "POST", path: "/jobs/nightly" });
+  await handle({ path: "/items" });
+  await handle({ method: "POST", path: "/jobs/nightly", headers: {} });
+  const log = await app(store).handle({ path: "/audit" });
+  assert.equal(log.status, 200);
+  assert.deepEqual(
+    log.body.map(({ keyName, method, path, status }) => ({ keyName, method, path, status })),
+    [
+      { keyName: "line cook", method: "POST", path: "/jobs/nightly", status: 403 },
+      { keyName: "line cook", method: "POST", path: "/recipes/1/cook", status: 200 },
+    ],
+  );
+  assert.equal(log.body[0].at, "2026-10-28T10:00:00.000Z");
+});
